<script setup lang="ts">import type {VersionSummaryViewModel} from "~/types/account-version-summary";import StorySlideShell from "../StorySlideShell.vue";const p=defineProps<{summary:VersionSummaryViewModel;pageIndex:number;pageTotal:number;active:boolean;reducedMotion:boolean}>();const inStreak=(d:string)=>Boolean(p.summary.calendarActivity?.streakStart&&p.summary.calendarActivity?.streakEnd&&d>=p.summary.calendarActivity.streakStart&&d<=p.summary.calendarActivity.streakEnd);</script>
<template><StorySlideShell :page-index="pageIndex" :page-total="pageTotal" :eyebrow="summary.copy.calendarActivity.eyebrow" :title="summary.copy.calendarActivity.title" :lead="summary.copy.calendarActivity.body" tone="royal" :active="active" :reduced-motion="reducedMotion"><div v-if="summary.calendarActivity" class="calendar"><div class="heat" data-animate><i v-for="day in summary.calendarActivity.days" :key="day.date" :class="{streak:inStreak(day.date)}" :style="{'--heat':day.intensity}" :title="`${day.date} · ${day.playCount}`"></i></div><div class="calendar__facts"><article data-animate><span>活跃天数</span><strong>{{summary.calendarActivity.activeDays}}</strong></article><article data-animate><span>最长连续</span><strong>{{summary.calendarActivity.longestStreak}} 天</strong><small>{{summary.calendarActivity.streakLabel}}</small></article></div></div></StorySlideShell></template>
